// Package ui holds the web UI shown in the WebView2 window: markup, behavior,
// styles and translations, embedded into the binary.
package ui

import (
	"embed"
	"encoding/json"
	"fmt"
	"strings"
)

// app.css is generated by build.ps1 (Tailwind) from style.css.
//
//go:embed index.html app.js app.css i18n
var files embed.FS

// Texts returns i18n/<lang>.json for a locale such as "fr-FR", falling back to
// English, with the chosen language added as "lang".
func Texts(locale string) (map[string]any, error) {
	lang, _, _ := strings.Cut(strings.ToLower(locale), "-")
	b, err := files.ReadFile("i18n/" + lang + ".json")
	if err != nil {
		lang = "en"
		if b, err = files.ReadFile("i18n/en.json"); err != nil {
			return nil, err
		}
	}
	var m map[string]any
	if err := json.Unmarshal(b, &m); err != nil {
		return nil, fmt.Errorf("i18n/%s.json: %w", lang, err)
	}
	m["lang"] = lang
	return m, nil
}

// Page returns index.html with its stylesheet and script inlined:
// the window loads it with SetHtml, which has no base URL for linked files.
func Page() string {
	html, _ := files.ReadFile("index.html")
	css, _ := files.ReadFile("app.css")
	js, _ := files.ReadFile("app.js")
	return strings.NewReplacer(
		`<link rel="stylesheet" href="app.css">`, "<style>"+string(css)+"</style>",
		`<script src="app.js"></script>`, "<script>"+string(js)+"</script>",
	).Replace(string(html))
}
